always-actions.script:
if (!resolvedSiteId) { const e=new Error('Site not found');e.moquiErrorKind='NotFound';throw e }
// the headers are per route (Shared/Headers.js): no-store and the shell's CSP until the route is known, and by default
const headers=ec.resource.script('component://mr-pass/screen/Shared/Headers.js')
headers.apply(null,'')
publicHost=String(publicHost || "").toLowerCase()
// what a Smithy form left for its next page (a new access token) does not outlive two minutes unread, in any app
if(ec.user.userId && ec.web?.sessionAttributes?.passSmithyFlash)ec.resource.script('component://mr-pass/screen/Smithy/Smithy.js').expireFlash()
siteId=resolvedSiteId
// a site's theme preview host (Commerce P5, F54) serves only the preview render (ShopPreview.xml, with its own
// headers), whatever the site's state: no site info, no shell
passPreview=ec.resource.script('component://mr-pass/screen/Shop/ShopPreview.js').isPreviewHost(siteId,publicHost)
if(passPreview){siteInfo={mounts:[]};passBases={};passApp=null;shopThemed=true;passPublicPage=false}
else{
siteInfo=ec.service.sync().throwOnError(true).name('pass.Facade.call#Operation').parameters({operation:'getSiteInfo',input:{siteId,hostname:publicHost}}).call().result
const passApps=ec.resource.script('component://mr-pass/service/pass/Apps.js')
passBases=Object.fromEntries(Object.entries(passApps).map(([app,v])=>[app,v.base]))
for (const mount of siteInfo.mounts || []) passBases[mount.app]=mount.pathPrefix==='/'?'':mount.pathPrefix
const requestPath=String(publicPath || '')
// the app the request is in, by its mount: the header shows that app's navigation
passApp=(siteInfo.mounts || [])
    .filter(m=>requestPath===m.pathPrefix || requestPath.startsWith((m.pathPrefix==='/'?'':m.pathPrefix)+'/'))
    .sort((a,b)=>b.pathPrefix.length-a.pathPrefix.length)[0]?.app || null
const appBase=passApp ? passBases[passApp] : ''
passHeaderPolicy=headers.apply(passApp,requestPath.slice(appBase.length) || '/',siteInfo.brand?.logoUrl)
// a page a shared cache may keep (Shop P3, F42): no session token and no signed-in state in it
passPublicPage=String(passHeaderPolicy.cacheControl).startsWith('public')
}
